-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L2 — Clearly trivial misstatements threshold
(1, 'Misstatements and Control Deficiencies', 'During the audit of Birchwood Retail, the engagement team finds a $12 rounding error in a prepaid insurance account. Overall materiality is $50,000. Under AU-C 450, the auditor would most likely classify this misstatement as:', '["A misstatement requiring projection to the population", "A misstatement that should be communicated to those charged with governance", "Clearly trivial and not required to be accumulated", "A judgmental misstatement requiring further evaluation"]'::jsonb, 2, 'AU-C 450.A2 defines clearly trivial misstatements as those that are inconsequential, whether individually or in aggregate, and of a wholly different (smaller) magnitude than materiality. A $12 error against $50,000 materiality falls well below any reasonable threshold. Unlike projected misstatements from sampling, clearly trivial items need not be accumulated on the summary of uncorrected misstatements.', 'easy', 2),

-- Q2: medium / L4 — Impact on audit opinion from aggregate uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Meridian Technologies has uncorrected misstatements totaling $180,000, with overall materiality set at $200,000 and performance materiality at $150,000. The misstatements affect revenue, inventory, and accounts receivable across three line items. The auditor should evaluate whether to:', '["Issue an unmodified opinion since the aggregate is below overall materiality", "Modify the opinion because the aggregate exceeds performance materiality and approaches overall materiality", "Withdraw from the engagement due to management integrity concerns", "Request management to increase the materiality threshold to accommodate the misstatements"]'::jsonb, 1, 'AU-C 450.11 requires the auditor to determine whether uncorrected misstatements are material, individually or in aggregate. When the aggregate ($180,000) exceeds performance materiality ($150,000) and approaches overall materiality ($200,000), modification should be considered rather than issuing an unmodified opinion. Simply noting the aggregate is below overall materiality ignores the proximity to that threshold and the spread across multiple line items.', 'medium', 4),

-- Q3: easy / L1 — Definition of "clearly trivial"
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does "clearly trivial" mean in the context of identified misstatements?', '["The misstatement is inconsequential, whether taken individually or in aggregate, and of a wholly different magnitude than materiality", "The misstatement is less than 5% of overall materiality", "The misstatement involves only rounding differences in the financial statements", "The misstatement has been corrected by management before year-end"]'::jsonb, 0, 'AU-C 450.A2 states that clearly trivial misstatements are of a wholly different (smaller) order of magnitude than materiality and are clearly inconsequential, whether taken individually or in aggregate. This is a qualitative threshold rather than a fixed percentage. A 5% firm policy is not incorrect because it conflicts with the standard, but because it substitutes a specific number for the standard''s qualitative judgment.', 'easy', 1),

-- Q4: medium / L3 — Rollover approach for evaluating prior-year uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the 2025 audit of Sterling Manufacturing, the auditor notes that a $40,000 depreciation error from 2024 remains uncorrected and continues to affect the 2025 income statement by $40,000. Using the rollover approach, the auditor evaluates this misstatement by:', '["Considering the cumulative $80,000 balance sheet effect plus the $40,000 income statement effect", "Considering only the $40,000 effect on the current-year financial statements as a whole", "Ignoring the misstatement since it originated in the prior year", "Considering only the $40,000 current-year effect on the income statement"]'::jsonb, 3, 'Under AU-C 450.A7, the rollover approach evaluates misstatements by the amount originating in the current year. Since the $40,000 depreciation error recurs annually, the rollover approach considers only the $40,000 current-year income statement impact. In contrast, the iron curtain approach would consider the full cumulative balance sheet effect. The rollover method does not ignore prior-year misstatements entirely but rather than aggregating all years, it focuses on the current-period originating amount.', 'medium', 3),

-- Q5: medium / L3 — Deficiency in design vs. operation
(1, 'Misstatements and Control Deficiencies', 'At Lakewood Distributing, management designed a three-way matching control requiring purchase orders, receiving reports, and vendor invoices to agree before payment. During testing, the auditor finds that accounts payable clerks routinely override the match requirement for invoices under $1,000. Under AU-C 265, this situation represents:', '["A deficiency in the design of the control", "A deficiency in the operation of the control", "An inherent limitation of internal control", "A compensating control failure"]'::jsonb, 1, 'AU-C 265.A1 distinguishes between design and operation deficiencies. A design deficiency exists when a control is missing or not properly designed to meet its objective. An operation deficiency exists when a properly designed control does not operate as designed. Here, the three-way match is properly designed but is being overridden in practice, making this an operating deficiency rather than a design flaw.', 'medium', 3),

-- Q6: medium / L3 — "Prudent official" test for control deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'While evaluating a control deficiency at Pine Valley Credit Union, the auditor applies the "prudent official" test described in auditing standards. The auditor identifies that the deficiency could allow a $75,000 misstatement to go undetected while materiality is $100,000. Under AU-C 265, the prudent official test asks whether:', '["A reasonable person relying on the financial statements would be influenced by the potential misstatement in making decisions", "Management has demonstrated an appropriate response to remediate the deficiency", "The deficiency has been reported in the prior year''s management letter", "The cost of correcting the deficiency exceeds the benefit of prevention"]'::jsonb, 0, 'AU-C 265.A12 references the prudent official concept, which asks whether a reasonable person in a governance role would conclude the deficiency merits attention. The test evaluates the significance of the potential impact rather than management''s remediation efforts. Unlike a cost-benefit analysis, the prudent official test focuses on whether the deficiency''s magnitude relative to materiality would concern a knowledgeable user.', 'medium', 3),

-- Q7: medium / L3 — IT general control deficiency cascading effect
(1, 'Misstatements and Control Deficiencies', 'During the audit of Concord Manufacturing, the auditor discovers that the IT administrator has unrestricted access to modify financial application data without logging or approval. This IT general control deficiency affects automated controls in revenue, purchasing, and payroll. Under AU-C 265, the auditor should evaluate this deficiency by considering:', '["Only the misstatements actually detected as a result of the access", "Only the largest potential misstatement in a single process", "The combined magnitude of potential misstatements across all affected processes", "Whether management intends to remediate the deficiency next fiscal year"]'::jsonb, 2, 'AU-C 265.A8 indicates that when a deficiency in IT general controls undermines the effectiveness of multiple application controls, the auditor should consider the aggregate potential misstatement across all affected systems. Rather than evaluating only actual misstatements found or only the largest single-process exposure, the auditor must assess the combined risk. An IT access weakness affecting revenue, purchasing, and payroll simultaneously creates pervasive risk that understates severity if evaluated in isolation.', 'medium', 3),

-- Q8: easy / L3 — Net vs. gross misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'At Cedar Ridge Hospitality, the auditor identifies a $30,000 overstatement in accounts receivable and a $28,000 understatement in accounts receivable from two unrelated errors. Materiality is $50,000. When evaluating these misstatements, the auditor should:', '["Net the two misstatements to $2,000 and conclude the effect is clearly trivial", "Consider only the larger $30,000 misstatement", "Report only the net $2,000 effect to those charged with governance", "Evaluate each misstatement individually and in aggregate without inappropriately netting"]'::jsonb, 3, 'AU-C 450.A4 requires the auditor to accumulate identified misstatements and evaluate them both individually and in aggregate. Unrelated misstatements should not be netted against each other because each may indicate distinct control issues. Rather than reducing these to a $2,000 net amount, the auditor must consider the $30,000 overstatement and $28,000 understatement separately, as netting would mask the true magnitude of errors in the account.', 'easy', 3),

-- Q9: medium / L2 — SUM schedule purpose and content
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Coast Enterprises, the engagement manager prepares a schedule listing all identified misstatements that management has not corrected, along with projected misstatements from sampling. Under AU-C 450, this schedule is commonly referred to as the:', '["Summary of uncorrected misstatements", "Schedule of findings and questioned costs", "Report on internal control deficiencies", "Audit difference memorandum"]'::jsonb, 0, 'AU-C 450.05-.06 requires the auditor to accumulate all identified misstatements during the audit other than those that are clearly trivial. This accumulated listing is commonly called the summary of uncorrected misstatements (SUM). Unlike the schedule of findings and questioned costs, which relates to governmental auditing under GAGAS, the SUM is used in all audits as the basis for evaluating the aggregate effect of uncorrected misstatements on the financial statements.', 'medium', 2),

-- Q10: hard / L3 — Iron curtain vs. rollover comparison
(1, 'Misstatements and Control Deficiencies', 'During the 2025 audit of Northstar Industries, the auditor identifies a cumulative balance sheet misstatement of $320,000 that has built up over four years from an uncorrected warranty accrual error. Each year''s income statement effect is approximately $80,000. Overall materiality is $250,000 and performance materiality is $175,000. Comparing the iron curtain and rollover approaches, the auditor determines that:', '["Both approaches yield the same conclusion because the misstatement is material under either method", "The iron curtain approach indicates a material misstatement while the rollover approach does not", "The rollover approach is more conservative because it captures the cumulative effect", "Neither approach indicates a material misstatement because warranty accruals involve estimation uncertainty"]'::jsonb, 1, 'Under AU-C 450.A7, the iron curtain approach evaluates the cumulative balance sheet effect ($320,000 exceeds $250,000 materiality), whereas the rollover approach evaluates only the current-year originating amount ($80,000, below $175,000 performance materiality). SAB 108/Topic 1N requires dual evaluation using both methods. The iron curtain approach is more conservative here rather than the rollover approach, which only captures the current-period origination.', 'hard', 3),

-- Q11: medium / L1 — Timing of written SD/MW communication
(1, 'Misstatements and Control Deficiencies', 'At Greenfield Industries, the auditor completed fieldwork on March 15, 2026, and the audit report is dated March 20, 2026. Under AU-C 265, when must the written communication of significant deficiencies and material weaknesses be issued?', '["Within 30 days after the audit report release date", "Before the audit report is issued", "Within 60 days after the end of the fiscal year", "No later than 60 days after the audit report release date"]'::jsonb, 3, 'AU-C 265.12 requires the auditor to communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the audit report release date. Although earlier communication is encouraged, it is not required before the report is issued. Unlike the 30-day or fiscal-year-end deadlines suggested in other options, the standard specifically ties the deadline to the report release date.', 'medium', 1),

-- Q12: easy / L2 — Management rep letter re: uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'At Oakmont Financial Group, the auditor prepares the management representation letter and includes a reference to uncorrected misstatements accumulated during the audit. Under AU-C 580, the management representation letter should include:', '["A statement that all misstatements have been corrected prior to issuance", "A description of each individual control deficiency identified", "Only those misstatements exceeding overall materiality", "A statement acknowledging the effects of uncorrected misstatements are immaterial, individually and in aggregate"]'::jsonb, 3, 'AU-C 580.A4 and AU-C 450.14 require the auditor to obtain a written representation from management that the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole. Rather than claiming all misstatements were corrected, the letter acknowledges the remaining uncorrected items and represents that they are not material. A summary of these items is typically attached.', 'easy', 2),

-- Q13: easy / L4 — Corrected misstatement pattern suggesting control issue
(1, 'Misstatements and Control Deficiencies', 'During the audit of Riverdale Savings Bank, the auditor identifies 15 revenue cutoff errors in December, all of which management subsequently corrects. Even after correction, the auditor should evaluate whether the pattern of errors suggests:', '["The need to withdraw from the engagement", "A control deficiency in the revenue cutoff process that warrants communication", "That the prior-year audit opinion should be withdrawn", "That materiality should be recalculated using a lower benchmark"]'::jsonb, 1, 'AU-C 450.08 and AU-C 265.A5 indicate that even when management corrects identified misstatements, the auditor should consider the nature and cause of the misstatements. A pattern of 15 cutoff errors suggests the revenue cutoff control is not operating effectively, which may constitute a significant deficiency or material weakness under AU-C 265. Although the errors were corrected, that does not eliminate the underlying control problem that allowed them to occur.', 'easy', 4),

-- Q14: hard / L1 — PCAOB integrated audit MW communication
(1, 'Misstatements and Control Deficiencies', 'In an integrated audit of a public company conducted under PCAOB standards, the auditor identifies a material weakness in internal control over financial reporting. Under PCAOB AS 2201, the auditor is required to:', '["Express an adverse opinion on internal control over financial reporting", "Communicate the material weakness only to management in writing", "Issue a qualified opinion on internal control over financial reporting", "Withdraw from the engagement and report to the SEC"]'::jsonb, 0, 'PCAOB AS 2201.92 states that if a material weakness exists as of the assessment date, the auditor must express an adverse opinion on the effectiveness of internal control over financial reporting. Unlike nonissuer audits under AU-C 265, where a material weakness is communicated but does not automatically trigger an adverse ICFR opinion, PCAOB standards mandate an adverse opinion. A qualified opinion on internal control is not permitted when a material weakness exists.', 'hard', 1),

-- Q15: medium / L1 — Content of management representation letter regarding misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Highland Manufacturing, the auditor finalizes the management representation letter. Under AU-C 580, which specific representation must management provide regarding misstatements identified during the audit?', '["That management has implemented all auditor recommendations to prevent future misstatements", "That all misstatements identified were caused by unintentional errors rather than fraud", "That management will correct all identified misstatements in the subsequent period", "That management believes the effects of uncorrected misstatements, summarized and attached, are immaterial to the financial statements as a whole"]'::jsonb, 3, 'AU-C 580.15 requires the management representation letter to include acknowledgment that the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole. Rather than requiring management to commit to future corrections or to characterize misstatements as errors versus fraud, the representation focuses on confirming immateriality of the remaining uncorrected items.', 'medium', 1),

-- Q16: hard / L1 — Subsequent events revealing prior-year misstatement
(1, 'Misstatements and Control Deficiencies', 'After issuing its 2025 audit report on Cascade Electronics, the auditor becomes aware that a $500,000 inventory valuation error existed at December 31, 2025, which exceeds materiality of $300,000. Under AU-C 560, the auditor''s primary obligation upon discovering this misstatement is to:', '["Take no action since the audit report has already been issued", "Document the finding for consideration during the next year''s audit", "Discuss the matter with management and determine whether the financial statements need revision", "Immediately notify the SEC of the material misstatement"]'::jsonb, 2, 'AU-C 560.14 requires the auditor to discuss the subsequently discovered facts with management and determine whether the financial statements need to be revised. Rather than deferring to the next year''s audit, the auditor must address a known material misstatement ($500,000 exceeds $300,000 materiality) in already-issued financial statements. Although regulatory notification may ultimately be necessary, the first step is discussion with management about revision.', 'hard', 1),

-- Q17: easy / L2 — Corrected misstatements as indicators for further procedures
(1, 'Misstatements and Control Deficiencies', 'At Pinewood Associates, the auditor identifies a $22,000 accounts payable understatement that management corrects immediately. Under AU-C 450, after management corrects the misstatement, the auditor should:', '["Remove the item from all audit documentation since it was resolved", "Consider whether the corrected misstatement indicates additional risks that require further audit procedures", "Issue an emphasis-of-matter paragraph noting the correction", "Increase materiality to account for management''s willingness to correct errors"]'::jsonb, 1, 'AU-C 450.08 requires the auditor to consider the nature and cause of corrected misstatements. Although management corrected the $22,000 error, the auditor should evaluate whether it signals a broader control weakness or an area requiring additional procedures. Removing corrected misstatements from documentation would violate AU-C 230 rather than fulfilling the auditor''s obligation to maintain a complete record of identified matters.', 'easy', 2),

-- Q18: medium / L2 — Qualitative factors making immaterial misstatement material
(1, 'Misstatements and Control Deficiencies', 'At Summit Healthcare Systems, the auditor discovers a $15,000 misclassification of an executive bonus as consulting expense. Overall materiality is $200,000. Although quantitatively immaterial, under AU-C 450 the auditor should consider which qualitative factor in evaluating this misstatement?', '["Whether the misstatement masks a change in earnings trend or affects compliance with debt covenants or regulatory requirements", "Whether the misstatement was detected through analytical procedures rather than substantive testing", "Whether the misstatement originated in the prior period", "Whether similar misstatements exist in comparable public companies"]'::jsonb, 0, 'AU-C 450.A16-.A17 states that qualitative factors may cause a quantitatively immaterial misstatement to be considered material. These include whether the misstatement masks an earnings trend, converts a loss to income, affects regulatory compliance, or conceals management compensation. Unlike the detection method or the existence of similar errors at other companies, these factors directly affect how financial statement users interpret the reported amounts.', 'medium', 2),

-- Q19: medium / L1 — Tolerable misstatement vs. overall materiality relationship
(1, 'Misstatements and Control Deficiencies', 'During the planning phase of an audit, the engagement partner sets overall materiality at $100,000. Under AU-C 320, performance materiality is set below overall materiality because it:', '["Represents the threshold below which misstatements are clearly trivial", "Establishes the minimum sample size for substantive testing", "Reduces the probability that the aggregate of uncorrected and undetected misstatements exceeds overall materiality", "Defines the amount above which all misstatements must be reported to management"]'::jsonb, 2, 'AU-C 320.09 states that performance materiality is set below overall materiality to reduce to an appropriately low level the probability that the aggregate of uncorrected and undetected misstatements exceeds materiality. Unlike the clearly trivial threshold, which is a separate and much lower amount, performance materiality serves as a planning buffer. It is not a sample size determinant, although it influences sample sizes indirectly.', 'medium', 1),

-- Q20: medium / L2 — Pervasive vs. material but not pervasive
(1, 'Misstatements and Control Deficiencies', 'At Eastfield Pharmaceuticals, uncorrected misstatements total $150,000 against overall materiality of $120,000. The misstatements are concentrated entirely in inventory valuation and do not affect other line items or disclosures. Under AU-C 705, the auditor should consider issuing:', '["An unmodified opinion with an emphasis-of-matter paragraph", "An adverse opinion due to pervasive material misstatement", "A disclaimer of opinion due to inability to obtain evidence", "A qualified opinion because the material misstatement is not pervasive"]'::jsonb, 3, 'AU-C 705.08-.09 distinguishes between material misstatements that are pervasive and those that are not. Pervasive effects are those not confined to specific elements, affect a substantial proportion of the financial statements, or are fundamental to users'' understanding. Although the $150,000 misstatement exceeds materiality ($120,000), it is confined to inventory valuation, warranting a qualified opinion rather than an adverse opinion that would be appropriate only for pervasive misstatements.', 'medium', 2),

-- Q21: medium / L4 — Fraud-related misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redstone Corp., the auditor discovers that the controller intentionally reclassified $45,000 of personal expenses as business travel. Overall materiality is $200,000. Under AU-C 240, the auditor should:', '["Evaluate the implications of the fraud on other aspects of the audit, including the reliability of management representations, regardless of the dollar amount", "Conclude the misstatement is immaterial because $45,000 is below the $200,000 materiality threshold", "Report the fraud directly to law enforcement before communicating with management", "Reclassify the misstatement as a judgmental difference since it involves estimates"]'::jsonb, 0, 'AU-C 240.35-.36 requires that when the auditor identifies a misstatement resulting from fraud, the auditor must consider the implications for other aspects of the audit, particularly the reliability of management representations. Unlike unintentional errors, a fraud-related misstatement cannot be evaluated solely on quantitative grounds because the intentional nature raises questions about management integrity and the potential for additional undetected fraud.', 'medium', 4),

-- Q22: hard / L1 — Discovery of material misstatement after report issuance
(1, 'Misstatements and Control Deficiencies', 'After the release of the audit report on Granite Industries, the auditor learns that a material misstatement existed in the audited financial statements. Management refuses to revise the financial statements or notify users. Under AU-C 560, what is the auditor''s responsibility?', '["No further action is required once the audit report is released", "The auditor should notify appropriate regulatory authorities and those known to be relying on the financial statements", "The auditor should reissue the audit report with a modified date", "The auditor should amend the prior-year working papers to reflect the misstatement"]'::jsonb, 1, 'AU-C 560.18-.20 states that when management does not take the necessary steps to ensure appropriate notification to users, the auditor should notify those charged with governance and take appropriate action to prevent reliance on the audit report. Rather than simply amending work papers or reissuing the report with a modified date, the auditor must actively prevent continued reliance, which may include notifying regulatory authorities.', 'hard', 1),

-- Q23: medium / L1 — Three severity categories of control deficiencies
(1, 'Misstatements and Control Deficiencies', 'The audit team at Clearwater Solutions identifies a control weakness during their risk assessment procedures. Under AU-C 265, control deficiencies are classified into which three severity categories?', '["Minor, moderate, and critical", "Inconsequential, reportable, and material", "Immaterial, significant, and pervasive", "Control deficiency, significant deficiency, and material weakness"]'::jsonb, 3, 'AU-C 265.05-.07 establishes three categories: a control deficiency (the base level), a significant deficiency (serious enough to merit governance attention), and a material weakness (reasonable possibility of undetected material misstatement). Unlike the minor/moderate/critical or immaterial/significant/pervasive frameworks suggested in other options, AU-C 265 uses these specific three terms as its classification hierarchy.', 'medium', 1),

-- Q24: medium / L3 — Compensating control reducing but not eliminating risk
(1, 'Misstatements and Control Deficiencies', 'At Horizon Media Group, the accounts payable supervisor does not review vendor master file changes, creating a control deficiency. However, management implemented a monthly reconciliation of the vendor master file to supporting documentation as a compensating control. The reconciliation is performed consistently but only catches changes after they have been in effect for up to 30 days. Under AU-C 265, the auditor should:', '["Eliminate the deficiency from the communication since the compensating control is in place", "Report the deficiency as a material weakness due to the 30-day detection gap", "Evaluate whether the compensating control sufficiently reduces the severity of the deficiency considering the residual risk from the detection delay", "Require management to implement a preventive control before issuing the audit report"]'::jsonb, 2, 'AU-C 265.A9-.A10 requires the auditor to consider compensating controls when evaluating the severity of identified deficiencies. Although a compensating control may reduce severity, it does not automatically eliminate the deficiency. Rather than removing the item from communication entirely, the auditor must assess whether the 30-day detection gap leaves sufficient residual risk to classify the deficiency as a significant deficiency or material weakness.', 'medium', 3),

-- Q25: easy / L2 — Communication of less severe deficiencies to management
(1, 'Misstatements and Control Deficiencies', 'During the audit of Aspen Ridge Properties, the auditor identifies several control deficiencies that are neither significant deficiencies nor material weaknesses. Under AU-C 265, the auditor should communicate these lesser deficiencies to:', '["Management, either in writing or orally", "Those charged with governance in writing", "Both management and those charged with governance in writing", "No party, since only significant deficiencies and material weaknesses require communication"]'::jsonb, 0, 'AU-C 265.13 states that the auditor should communicate to management control deficiencies of sufficient importance to merit attention, even if not rising to significant deficiency level. This communication may be written or oral. Unlike significant deficiencies and material weaknesses, which require written communication to those charged with governance, lesser deficiencies are communicated to management only.', 'easy', 2),

-- Q26: hard / L3 — Multiple overlapping control deficiencies evaluation
(1, 'Misstatements and Control Deficiencies', 'The auditor of Westbrook Financial identifies three separate control deficiencies in the loan loss reserve process: (1) the credit analyst does not independently verify borrower financial data, (2) the model used for collective reserves has not been validated in three years, and (3) management override approvals for reserve adjustments are not documented. Individually, each deficiency could result in misstatements of $40,000, $60,000, and $50,000, respectively. Overall materiality is $200,000. Under AU-C 265, the auditor should:', '["Report each as a separate control deficiency since none individually reaches materiality", "Evaluate the combined effect because the deficiencies relate to the same significant account and assertion, potentially constituting a material weakness", "Average the three potential misstatements to determine a single severity classification", "Classify only the $60,000 model validation deficiency as a significant deficiency"]'::jsonb, 1, 'AU-C 265.A11 requires the auditor to consider whether individual deficiencies combine to create a significant deficiency or material weakness. Rather than evaluating each deficiency in isolation, the auditor must assess the combined potential impact ($150,000 of $200,000 materiality) when multiple deficiencies affect the same account and assertion. Although none individually reaches materiality, their overlapping nature means failures compound, potentially rising to a material weakness.', 'hard', 3),

-- Q27: easy / L2 — Misstatement affecting qualitative footnote disclosures
(1, 'Misstatements and Control Deficiencies', 'During the audit of Maple Grove Hospital, the auditor discovers that a required footnote disclosure about related-party transactions was omitted. The dollar amount of the transactions is $8,000 against materiality of $150,000. Under AU-C 450, the auditor should:', '["Ignore the omission since the dollar amount is below materiality", "Consider only whether the omission is quantitatively material", "Project the omission to the population of all footnote disclosures", "Evaluate whether the omission is qualitatively material regardless of the dollar amount involved"]'::jsonb, 3, 'AU-C 450.A16-.A17 requires the auditor to evaluate misstatements for both quantitative and qualitative materiality. Unlike purely numerical errors, related-party disclosure omissions may be qualitatively material even when dollar amounts are small because users rely on such disclosures to evaluate management integrity. The omission cannot be assessed solely on quantitative grounds, as the nature of the information is inherently significant.', 'easy', 2),

-- Q28: easy / L4 — Evaluating recurring trivial errors as systemic control issue
(1, 'Misstatements and Control Deficiencies', 'At Silverton Technologies, the auditor identifies eight separate errors in the monthly payroll accrual over the 12-month period, all of which management corrects before year-end. The errors range from $500 to $3,000 each, all individually below the clearly trivial threshold. The auditor should:', '["Take no further action since all errors are below the clearly trivial threshold and were corrected", "Report each corrected error individually to those charged with governance", "Evaluate whether the recurring pattern of errors, despite being individually trivial, indicates a systemic control deficiency in the payroll accrual process", "Request management provide a written representation that all payroll errors have been identified"]'::jsonb, 2, 'AU-C 265.A5 and AU-C 450.08 indicate that the auditor should consider the nature and pattern of misstatements, even corrected ones. Although each error is individually below the clearly trivial threshold, eight recurring errors in a single process over 12 months suggest a systemic control weakness rather than isolated incidents. The pattern may constitute a control deficiency, significant deficiency, or material weakness depending on the potential magnitude of undetected errors.', 'easy', 4),

-- Q29: medium / L4 — Multiple immaterial misstatements trending same direction (bias)
(1, 'Misstatements and Control Deficiencies', 'The auditor of Harbor Logistics accumulates 12 uncorrected misstatements, all of which overstate revenue by amounts ranging from $5,000 to $18,000. The total is $110,000, and overall materiality is $150,000. All misstatements involve premature revenue recognition in the final month of the fiscal year. Under AU-C 240, the auditor should evaluate whether:', '["The consistent pattern of overstatement suggests possible management bias or fraud, requiring expanded procedures and reconsideration of assessed risks", "The misstatements are acceptable because the aggregate remains below materiality", "Each misstatement should be projected individually to the revenue population", "The auditor should adjust materiality upward to reflect the recurring nature of the misstatements"]'::jsonb, 0, 'AU-C 240.A53 and AU-C 450.A17 require the auditor to evaluate whether misstatements trending in the same direction indicate possible management bias. Twelve overstatements of revenue all involving premature recognition is a strong indicator of intentional bias. Rather than accepting the aggregate as immaterial simply because it falls below the $150,000 threshold, the auditor must reconsider fraud risk and evaluate the implications of the directional pattern.', 'medium', 4),

-- Q30: hard / L2 — Successor auditor discovering prior-year material misstatement
(1, 'Misstatements and Control Deficiencies', 'During the 2026 audit of Atlas Global Corp., the successor auditor discovers that a material misstatement existed in the 2025 financial statements audited by the predecessor, resulting from a material weakness that existed throughout 2025. Under AU-C 510 and AU-C 560, the successor auditor should:', '["Ignore the prior-year issue since it falls outside the scope of the current engagement", "Request that the predecessor auditor reissue the 2025 report with a modified opinion", "Communicate the matter to management and those charged with governance and evaluate the impact on both the 2025 and 2026 financial statements", "Issue an adverse opinion on the 2026 financial statements due to the prior-year error"]'::jsonb, 2, 'AU-C 560.16 and AU-C 510.09-.10 require the successor auditor to communicate to management and those charged with governance when a material misstatement is discovered in previously issued financial statements. Rather than ignoring the issue or reissuing the predecessor''s report (which the successor cannot do), the successor should request that the entity inform the predecessor auditor. Although the matter affects both years, automatically issuing an adverse 2026 opinion would be inappropriate without first evaluating whether restatement corrects the comparative presentation.', 'hard', 2)
;

COMMIT;
